let EXTRA = [];
try {
  EXTRA = window.CineExtra;
} catch (_) {
  EXTRA = [];
}

const normTitlePre = (t) =>
  String(t || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const normTitle = (t) =>
  String(t || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

