const ALL_INDUSTRIES = Object.keys(INDUSTRIES).map((code) => ({ code, name: INDUSTRIES[code] }));

window.CineData = { movies, byId, ALL_GENRES, ALL_INDUSTRIES, INDUSTRIES, slugify };

